css:
.scene {
  position: relative;
  height: 260px;
  margin: 16px;
}

.group {
  position: relative;
  isolation: isolate; /* new stacking context */
}

.layer {
  position: absolute;
  width: 150px;
  height: 100px;
  padding: 8px;
  border: 1px solid #18181b;
  border-radius: 6px;
}

.a { top: 0;     left: 0;     z-index: 3;   background: #fed7aa; }
.b { top: 50px;  left: 70px;  z-index: 999; background: #bfdbfe; }
.c { top: 100px; left: 140px; z-index: 2;   background: #bbf7d0; }
